// Generated Base64 Vehicle Sprites for 100% reliable instant rendering
import 'dart:convert';
import 'dart:typed_data';

class VehicleImageData {
  static final Map<String, Uint8List> _cache = {};

  static Uint8List? getBytes(String key) {
    if (_cache.containsKey(key)) return _cache[key];
    final b64 = _base64Map[key];
    if (b64 == null) return null;
    final bytes = base64Decode(b64);
    _cache[key] = bytes;
    return bytes;
  }

  static final Map<String, String> _base64Map = {
    'jeepney': '',
    'tricycle': '',
    'motorcycle': '',
  };
}
